		"config_auto_str_54":"<div class='bt-form pd20'>\t\t\t<div class='line'><span class='tname'>Benutzername</span>\ t\t\t\t<div class='info-r'><input class='bt-input-text' type='text' name='password1' id='p1' value='' placeholder='Neuer Benutzername' style='width:70%'/ ></div>\t\t\t</div>\t\t\t<div class='line'>\t\t\t\t<span class='tname'>Wiederholen</span>\ t\t\t\t<div class='info-r'><input class='bt-input-text' type='text' name='password2' id='p2' value='' placeholder='Noch einmal eingeben' style='width:70%'/ ></div>\t\t\t</div>\t\t</div>",
