		"config_auto_str_143":"<li>Das kostenlose 90-Tage-Zertifikat wurde erfolgreich bereitgestellt und SSL im Control Panel aktiviert. </li>\t\t\t\t\t\t\t\t\t\t<li>Kostenloses Zertifikat über ACME beantragt, Gültigkeitsdauer 3 Monate, wird nach Ablauf standardmäßig automatisch verlängert. </li>\t\t\t\t\t\t\t\t\t\t<li>Wenn Sie ein neues Zertifikat beantragen oder das bestehende ersetzen möchten, klicken Sie einfach auf „Verlängern“.</li>",
