		"config_auto_str_158":"<div class='pd20'>\t\t\t\t\t<button class='btn btn-success btn-sm refresh_log'>Protokoll aktualisieren</button>\t\t\t\t\t<div class='divtable mt10'>\ t\t\t\t\t\t<table class='table table-hover'>\t\t\t\t\t\t\t<thead>\t\t\t\t\ t\t\t\t<tr><th>Aktionsart</th><th>Aktionszeit</th><th>Protokoll</th></tr>\t\t\t\t\t\t\t</thead>\t\t\t\ t\t\t\t<tbody id='logs_list'></tbody>\t\t\t\t\t\t</table>\t\t\t\t\t</div>\t\t\t\t</div>",
