		"site_auto_str_148":"<form id='form_proxy' class='divtable pd15' style='padding-bottom: 10px'>\t\t\t\t<div class='line'>\t\t\t\t\t<span class='tname' style='line-height:20px;' >Proxy aktivieren</span>\t\t\t\t\t<div class='info-r ml0 mt5'>\t\t\t\t\t\t<input name='open_proxy' class='btswitch btswitch-ios' type='checkbox' checked>\ t\t\t\t\t\t<label id='open_proxy' class='btswitch-btn' for='openProxy' style='float:left'></label>\ t\t\t\t\t\t<div style='display: inline-block'>\t\t\t\t\t\t\t<span class='tname' style='position: relative; top: -5px;'>Zwischenspeichern?</span>\t\t\t\t\t\t\t<input class='btswitch btswitch-ios' type='checkbox' name='open_cache'>\t\t\t\ t\t\t\t<label class='btswitch-btn' id='open_cache' for='openCache' style='float:left'></label>\t\t\t\t\t\t</div>\ t\t\t\t\t\t<div style='display: inline-block'>\t\t\t\t\t\t\t<span class='tname' style='position: relative; top: -5px;'>Domänenübergreifend?</span>\t\t\t\t\t\t\t<input class='btswitch btswitch-ios' type='checkbox' name='open_cors'>\t\t\t\ t\t\t\t<label class='btswitch-btn' id='open_cors' for='open_cors' style='float:left'></label>\t\t\t\t\t\t</div>\ t\t\t\t\t\t<div style='display: inline-block'>\t\t\t\t\t\t\t<span class='tname' style='position: relative; top: -5px;'>Ist es H3</span>\t\t\t\t\t\t\t<input class='btswitch btswitch-ios' type='checkbox' name='open_http3'>\t\t\t\ t\t\t\t<label class='btswitch-btn' id='open_http3' for='open_http3' style='float:left'></label>\t\t\t\t\t\t</div>\t\t\t\t\t</div>\ t\t\t\t</div>\t\t\t\t<div class='line'>\t\t\t\t\t<span class='tname'>Name</span>\t\t\t\t\t<div class='info-r ml0'>\ t\t\t\t\t<input name='name' value='index' placeholder='Bitte Namen eingeben' class='bt-input-text mr5' type='text' style='width:200px''>\t\t\t\t\t</div>\ t\t\t\t</div>\t\t\t\t<div class='line' style='display:none' id='cache_time'>\t\t\t\t\t<span class='tname'>Cache-Zeit</span>\ t\t\t\t\t<div class='info-r ml0'>\t\t\t\t\t<input name='cache_time' value='1' class='bt-input-text mr5' type='number' style='width:200px''>Minuten\ t\t\t\t\t</div>\t\t\t\t</div>\t\t\t\t<div class='line'>\t\t\t\t\t<span class='tname'>Proxy-Verzeichnis</span>\ t\t\t\t\t<div class='info-r ml0'>\t\t\t\t\t<input name='from' value='/' placeholder='/' class='bt-input-text mr5' type='text' style='width:200px''>\ t\t\t\t\t</div>\t\t\t\t</div>\t\t\t\t<div class='line'>\t\t\t\t\t<span class='tname'>Ziel-URL</span>\t\t\t\ t\t<div class='info-r ml0'>\t\t\t\t\t<input name='proxy_url' class='bt-input-text mr5' type='text' value='http://127.0.0.1' style='width:150px; float: left; margin-right: 5px'>\t\t\t\t\t<span style='float: left; margin-right: 5px; line-height: 30px; font-weight: bold;'>:</span>\t\t\t\t\t<input name='proxy_port' class='bt-input-text mr5' type='number' placeholder='Port' style='width:65px; float: left;margin-right:15px'>\t\t\t\t\t<input name='to' type='hidden' value='http://127.0.0.1'>\t\t\t\ t\t<span class='tname' style='width:90px'>Domain senden </span>\t\t\t\t\t<input name='host' value='$host' class='bt-input-text mr5' type='text' style='width:100px'>\ t\t\t\t\t</div>\t\t\t\t</div>\t\t\t\t<input name='id' value='' type='hidden'>\t\t\t\t<div class='help-info-text c7'>\ t\t\t\t\t<ul class='help-info-text c7'>\t\t\t\t\t<li>Proxy-Verzeichnis: Beim Aufrufen dieses Verzeichnisses wird der Inhalt der Ziel-URL zurückgegeben und angezeigt</li>\t\t\t\t\t<li>Ziel-URL: Geben Sie hier die Website ein, für die Sie einen Proxy nutzen möchten. Die Ziel-URL muss eine ordnungsgemäß zugängliche URL sein, andernfalls wird ein Fehler zurückgegeben</li>\t\t\t\ t\t<li>Zu sendende Domain: Fügt die Domain zum Request-Header hinzu und leitet sie an den Proxy-Server weiter. Standardmäßig ist dies die Domain der Ziel-URL. Eine falsche Einstellung kann dazu führen, dass der Proxy nicht ordnungsgemäß funktioniert</li>\t\t\t\t\t</ul>\t\t\t\t</div>\t\t\t\t</form>",
