		"site_auto_str_242":"</button>\t\t\t\t\t\t\t</div>\t\t\t\t\t\t\t<span id='php_w' style='color:red;margin-left: 32px;' ></span>\t\t\t\t\t\t</div>\t\t\t\t\t\t\t<ul class='help-info-text c7 ptb10'>\t\t\t\t\ t\t\t\t<li>Bitte wählen Sie die Version entsprechend Ihren Programmieranforderungen aus</li>\t\t\t\t\t\t\t\t<li>Verwenden Sie PHP 5.2 möglichst nur, wenn es unbedingt notwendig ist, da dies die Sicherheit Ihres Servers beeinträchtigt; </li>\t\t\t\t\t\t\t\t<li>PHP 7 unterstützt keine MySQL-Erweiterung; standardmäßig werden mysqli und mysql-pdo installiert. </li>\t\t\t\t\t\t\t</ul>\t\t\t\t\t\t</div>\t\t\t\t\t</div>",
